stats<-if(consensus_exists)readRDS(file.path(ROOT,'03_cellchat_consensus/consensus_network.rds'))$statistics else NULL
cellchat_status<-if(success==nrow(cfg$samples) && consensus_exists && figures_exist && all(stats$n_missing_eligible==0))'PASS' else if(success>0 || attempted==0)'PARTIAL' else 'FAIL'
nn_status_path<-file.path(ROOT,'05_nichenet_preflight/NICHENET_STATUS.txt')
nn_status<-if(file.exists(nn_status_path))trimws(readLines(nn_status_path)[1]) else 'PREFLIGHT'
overall_status<-if(cellchat_status=='FAIL')'FAIL' else if(cellchat_status=='PASS' && nn_status=='READY')'PASS' else 'PARTIAL'
markdown_table<-function(d) {
 if(is.null(d)||!nrow(d))return('NOT AVAILABLE: inference not completed.')
 d<-copy(d);for(n in names(d))d[[n]]<-as.character(d[[n]])
 c(paste0('| ',paste(names(d),collapse=' | '),' |'),paste0('| ',paste(rep('---',ncol(d)),collapse=' | '),' |'),apply(d,1,function(v)paste0('| ',paste(v,collapse=' | '),' |')))
}
edge_top<-function(kind) {
 if(is.null(stats))return(NULL)
 z<-copy(stats[display_strength>0]);if(kind=='out')z<-z[grepl('^Fibro_C',source)] else if(kind=='in')z<-z[grepl('^Fibro_C',target)]
 setorder(z,-consensus_strength,-prevalence)
 z[1:min(12L,.N),.(source,target,n_eligible,n_detected,prevalence,consensus_strength)]
}
nn_metrics_path<-file.path(ROOT,'05_nichenet_preflight/nichenet_preflight_metrics.tsv')
nn_summary<-if(file.exists(nn_metrics_path))fread(nn_metrics_path)[metric%in%c('package_version','source_commit','resource_record','ligand_target_dimensions','LR_unique_pairs','geneset_oi','ligand_activity_run')] else NULL
