preflight<-audit[metric%in%c('Seurat_version','SeuratObject_version','CellChat_version','total_cells','biological_samples','patient_number','biological_sample_field','patient_uid_field','dataset_field','major_field','fibro_subtype_field','RNA_assay_structure','normalized_layer','normalization','scale_factor','primary_included_cells','excluded_unresolved_cycling','excluded_previous_fibro_decisions')]
