 if(file.exists(file.path(ROOT,'03_cellchat_consensus/CellChat_consensus_sensitivity.md')))paste0('- Sensitivity report: `',file.path(ROOT,'03_cellchat_consensus/CellChat_consensus_sensitivity.md'),'`.') else '- Sensitivity results and LLPS integration are not yet computed.',
